package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
// The original implementation walked the input one byte at a time while
// juggling several flags (header level, list depth, "list opened", "header
// ended") and a handful of one-shot strings.Replace calls. It worked, but
// the state machine was hard to follow.
//
// The rewrite keeps the same overall strategy — emphasis markers are
// substituted up front, then the document is parsed — but parses line by
// line instead of byte by byte. Each line is independently one of:
//
//   - a header:  one to six leading '#' characters, followed by a space
//   - a list item: a leading '* '
//   - plain text: wrapped in a <p> element
//
// Any line that is not a list item closes an open list, and any line that
// is not a header closes an open header, so no flags need to carry state
// across lines except "are we inside a list".

// Render translates markdown to HTML
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if level, ok := headerLevel(line); ok {
			html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", level, headerText(line, level), level))
			continue
		}
		if strings.HasPrefix(line, "* ") {
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + line[2:] + "</li>")
			continue
		}
		if inList {
			html.WriteString("</ul>")
			inList = false
		}
		html.WriteString("<p>" + line + "</p>")
	}
	if inList {
		html.WriteString("</ul>")
	}
	return html.String()
}
```

